const t0 = Date.now();
const msg = await client.messages.create({ model: MODEL_ID, max_tokens: 1024, messages });
logger.info({
  request_id: msg._request_id,
  model: msg.model,
  prompt_version: PROMPT_VERSION,
  stop_reason: msg.stop_reason,
  input_tokens: msg.usage.input_tokens,
  output_tokens: msg.usage.output_tokens,
  cache_read_tokens: msg.usage.cache_read_input_tokens,
  latency_ms: Date.now() - t0,
});
if (msg.stop_reason === "max_tokens") metrics.increment("llm.truncated");

from tenacity import retry, stop_after_attempt, wait_exponential
from anthropic import Anthropic

client = Anthropic()  # SDK defaults

@retry(stop=stop_after_attempt(5), wait=wait_exponential(min=1, max=30))
def classify(text: str):
    return client.messages.create(model=MODEL_ID, max_tokens=50,
        messages=[{"role": "user", "content": text}])

const page = await client.messages.batches.list({ limit: 20 });
for (const batch of page.data) {
  await reconcile(batch);
}
console.log("reconciled all batches");

for block in msg.content:
    if block.type == "tool_use":
        args = json.loads(block.input)
        result = run_tool(block.name, **args)

const results = await Promise.all(
  tickets.map((t) =>
    client.messages.create({
      model: MODEL_ID,
      max_tokens: 300,
      messages: [{ role: "user", content: prompt(t) }],
    }),
  ),
);

